#!/usr/bin/env python3"""Sisyphus plan-progress verifier (M0 capa anti-olvido).Lee `.sisyphus/progress.json` (estado canonico del plan M0-M13) y comprueba:  1. Toda tarea marcada `status="done"` tiene su `evidence_file` presente en el     arbol de git (no solo en working tree) y el `committed_sha` existe en git.  2. El orden de `status="done"` respeta el campo `order` (no puede estar "done"     un milestone cuyos predecesores no lo esten).  3. `in_progress` como maximo uno a la vez.Salida con codigo de exito:  0  -> todo consistente (o todo pending: caso inicial aceptable)  1  -> inconsistencia detectada (bloquear commit / CI)Uso:  python scripts/check-plan-progress.py            # modo normal  python scripts/check-plan-progress.py --strict   # exige que NINGUN task quede pendingEste script es de SOLO LECTURA: no modifica el progreso ni el arbol."""from __future__ import annotationsimport argparseimport jsonimport subprocessimport sysfrom pathlib import PathROOT = Path(__file__).resolve().parent.parentPROGRESS = ROOT / ".sisyphus" / "progress.json"class Colors:    RED = "\033[31m"    GREEN = "\033[32m"    YELLOW = "\033[33m"    RESET = "\033[0m"    BOLD = "\033[1m"def _git(*args: str) -> str | None:    """Run a git command in the repo root, return stdout or None on failure."""    try:        result = subprocess.run(            ["git", *args],            cwd=str(ROOT),            capture_output=True,            text=True,            timeout=15,        )        if result.returncode != 0:            return None        return result.stdout.strip()    except (subprocess.SubprocessError, OSError):        return Nonedef _sha_exists(sha: str) -> bool:    if not sha:        return False    return _git("cat-file", "-e", sha) is not Nonedef _file_in_git(path: str) -> bool:    """True si el path esta tracked (commiteado) en el HEAD del arbol."""    if not path:        return False    # Quitar SOLO un prefijo './' literal. NO usar lstrip (elimina cualquier    # combinacion de '.' y '/', rompiendo paths como '.sisyphus/...').    rel = path[2:] if path.startswith("./") else path    out = _git("ls-files", "--error-unmatch", rel)    if out is not None:        return True    return _git("cat-file", "-e", f"HEAD:{rel}") is not Nonedef _print(msg: str, color: str = "") -> None:    print(f"{color}{msg}{Colors.RESET if color else ''}")def main() -> int:    parser = argparse.ArgumentParser(description="Verifica el progreso del plan Sisyphus.")    parser.add_argument("--strict", action="store_true",                        help="Falla si queda cualquier tarea pendiente (no solo inconsistencias).")    args = parser.parse_args()    if not PROGRESS.exists():        _print(f"[FAIL] No existe {PROGRESS.relative_to(ROOT)}", Colors.RED)        return 1    try:        data = json.loads(PROGRESS.read_text(encoding="utf-8"))    except json.JSONDecodeError as exc:        _print(f"[FAIL] {PROGRESS.relative_to(ROOT)} no es JSON valido: {exc}", Colors.RED)        return 1    order: list[str] = data.get("order", [])    tasks: list[dict] = data.get("tasks", [])    if not tasks:        _print("[FAIL] progress.json no tiene tareas.", Colors.RED)        return 1    # Validar que los IDs de task coinciden con el orden declarado.    task_ids = [t["id"] for t in tasks]    if order and task_ids != order:        _print(            f"[FAIL] El orden declarado ({order}) no coincide con los IDs de tareas "            f"({task_ids}). Actualiza progress.json.",            Colors.RED,        )        return 1    errors: list[str] = []    by_id = {t["id"]: t for t in tasks}    # 1. Como maximo una tarea in_progress.    in_progress = [t["id"] for t in tasks if t.get("status") == "in_progress"]    if len(in_progress) > 1:        errors.append(            f"Hay {len(in_progress)} tareas in_progress a la vez ({in_progress}). "            f"Permitido: como mucho 1."        )    # 2. Orden de 'done': un milestone solo puede estar done si todos sus    #    predecesores en 'order' tambien lo estan.    if order:        done = {t["id"] for t in tasks if t.get("status") == "done"}        for i, mid in enumerate(order):            if mid in done:                preds = order[:i]                missing = [p for p in preds if p not in done]                if missing:                    errors.append(                        f"{mid} esta 'done' pero sus predecesores no: {missing}. "                        f"El orden exige {order}."                    )    # 3. Toda tarea 'done' debe tener evidence_file commiteado y sha valido.    for t in tasks:        if t.get("status") != "done":            continue        tid = t["id"]        ev = t.get("evidence_file", "")        if not ev:            errors.append(f"{tid}: marcada 'done' sin evidence_file.")            continue        if not (ROOT / ev).exists():            errors.append(f"{tid}: evidence_file '{ev}' no existe en el working tree.")        elif not _file_in_git(ev):            errors.append(                f"{tid}: evidence_file '{ev}' NO esta commiteado. "                f"Git add + commit antes de marcar 'done'."            )        sha = t.get("committed_sha") or ""        if not sha or sha == "PENDING":            errors.append(                f"{tid}: marcada 'done' con committed_sha vacio/PENDING. "                f"Tras commitear, anota el SHA real (git rev-parse HEAD)."            )        elif not _sha_exists(sha):            errors.append(f"{tid}: committed_sha '{sha}' no existe en git.")    # 4. Modo estricto: ninguna tarea puede quedar pending/skipped.    if args.strict:        unfinished = [t["id"] for t in tasks if t.get("status") != "done"]        if unfinished:            errors.append(                f"--strict: quedan {len(unfinished)} tareas sin completar: {unfinished}"            )    # ── Reporte ───────────────────────────────────────────────────────────────    done = [t["id"] for t in tasks if t.get("status") == "done"]    prog = [t["id"] for t in tasks if t.get("status") == "in_progress"]    pend = [t["id"] for t in tasks if t.get("status") == "pending"]    _print(f"\n{Colors.BOLD}Sisyphus plan: {data.get('scope', '?')}{Colors.RESET}")    total = len(tasks)    _print(f"  done:        {len(done)}/{total}  {done}")    _print(f"  in_progress: {len(prog)}        {prog}")    _print(f"  pending:     {len(pend)}        {pend}")    if errors:        _print(f"\n{Colors.RED}{Colors.BOLD}[FAIL] {len(errors)} inconsistencia(s):", Colors.RESET)        for e in errors:            _print(f"  - {e}", Colors.RED)        _print(            "\nResolucion: marca 'done' SOLO tras commitear el evidence_file y "            "anotar el SHA; respeta el orden declarado en 'order'.",            Colors.YELLOW,        )        return 1    _print(f"\n{Colors.GREEN}[OK] progreso consistente.{Colors.RESET}")    return 0if __name__ == "__main__":    raise SystemExit(main())